static void velacare_on_state_change(int new_state, int old_state,
                                     const char *reason)
{
    VELACARE_LOG("State: %s -> %s (%s)",
                 velacare_state_name(old_state),
                 velacare_state_name(new_state),
                 reason ? reason : "N/A");

    /* 更新 LVGL 屏幕显示 */

    velacare_lvgl_update_state(new_state);

