    if (wifiOnline) {
      wifiConnecting = false;
      if (configPortalActive) {
        WiFi.softAPdisconnect(true);
        WiFi.mode(WIFI_STA);
        configPortalActive = false;
        Serial.println("WIFI setup access point stopped");
