    } else {
      Serial.println("WIFI disconnected");
      wifiConnecting = true;
      wifiConnectStartedMs = millis();
    }
    printStatus();
  }
  if (wifiConnecting && !nowOnline &&
      static_cast<uint32_t>(millis() - wifiConnectStartedMs) >=
          kWifiConnectTimeoutMs) {
