    /* 更新 LVGL 屏幕显示 */

    velacare_lvgl_update_state(new_state);

    /* 紧急状态触发 TTS 告警 */

    if (new_state == VELACARE_STATE_EMERGENCY)
        {
            velacare_tts_speak("紧急情况，请注意安全");
        }
