/****************************************************************************
 * apps/velacare/velacare_skill.c — Skill 部署
 *
 * 把编译时内置的 4 个 Skill 拷到 /data/agent/skills/
 * ai_agent 启动时 (或 reload 时) 扫描此目录
 *
 * 文件名约定: velacare-<skill-name>.md
 * Skill 标题 (md 首行 #) 是真正起作用的标识
 ****************************************************************************/

#include "velacare_skill.h"
#include <nuttx/config.h>
#include <syslog.h>
#include <stdio.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>

#define VELACARE_TAG "[velacare-skill]"

#define SKILL_DIR "/data/agent/skills"

int velacare_skill_install(const char *name, const char *content)
{
    char path[128];
    snprintf(path, sizeof(path), "%s/velacare-%s.md", SKILL_DIR, name);

    /* 幂等: 已存在且未变更则跳过 (用 size 判断) */
    struct stat st;
    if (stat(path, &st) == 0 && (size_t)st.st_size == strlen(content))
    {
        return 0;
    }

    int fd = open(path, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd < 0)
    {
        syslog(LOG_ERR, VELACARE_TAG " 打开 %s 失败\n", path);
        return -1;
    }
    write(fd, content, strlen(content));
    close(fd);

    syslog(LOG_INFO, VELACARE_TAG " 安装 Skill: %s (%zu 字节)\n",
           path, strlen(content));
    return 0;
}

/* 4 个 Skill 源码, 由 Makefile 把 .md 转成 .c 字符串数组 */
extern const char velacare_skill_home_safety_guard[];
extern const char velacare_skill_elder_care_reminder[];
extern const char velacare_skill_voice_alert[];
extern const char velacare_skill_daily_summary[];

int velacare_skill_install_all(void)
{
    mkdir(SKILL_DIR, 0755);

    velacare_skill_install("home-safety-guard",   velacare_skill_home_safety_guard);
    velacare_skill_install("elder-care-reminder", velacare_skill_elder_care_reminder);
    velacare_skill_install("voice-alert",         velacare_skill_voice_alert);
    velacare_skill_install("daily-summary",       velacare_skill_daily_summary);

    return 0;
}
