static void show_page(int selected)
{
  int i;

  if (g_ui == NULL || selected < 0 || selected >= PAGE_COUNT)
    {
      return;
    }

  for (i = 0; i < PAGE_COUNT; i++)
    {
      if (i == selected)
        {
          lv_obj_remove_flag(g_ui->page[i], LV_OBJ_FLAG_HIDDEN);
        }
      else
        {
          lv_obj_add_flag(g_ui->page[i], LV_OBJ_FLAG_HIDDEN);
        }

      lv_obj_set_style_bg_color(g_ui->nav_btn[i],
        lv_color_hex(i == selected ? 0x15803d : 0xe2e8f0), 0);
      lv_obj_set_style_text_color(g_ui->nav_label[i],
        lv_color_hex(i == selected ? 0xffffff : 0x334155), 0);
    }
}

static void nav_event(lv_event_t *event)
{
  if (lv_event_get_code(event) == LV_EVENT_CLICKED)
    {
      show_page((int)(intptr_t)lv_event_get_user_data(event));
    }
}

static void help_reset_button(void)
{
  lv_label_set_text(g_ui->help_btn_label, "长按求助");
  lv_obj_set_style_bg_color(g_ui->help_button,
                            lv_color_hex(0xdc2626), 0);
}

static void help_timer_event(lv_timer_t *timer)
{
  struct ui_objects_s *ui = lv_timer_get_user_data(timer);

  ui->help_countdown--;
  if (ui->help_countdown > 0)
    {
      lv_label_set_text_fmt(ui->help_btn_label, "取消求助 %d",
                            ui->help_countdown);
      return;
    }

  lv_timer_delete(ui->help_timer);
  ui->help_timer = NULL;
  help_reset_button();
  if (velacare_sensor_send_sos() == 0)
    {
      lv_label_set_text(ui->help_notice, "求助已送达家庭网关");
      lv_obj_set_style_text_color(ui->help_notice,
                                  lv_color_hex(0xb45309), 0);
    }
  else
    {
      lv_label_set_text(ui->help_notice, "网关离线，求助未发送");
      lv_obj_set_style_text_color(ui->help_notice,
                                  lv_color_hex(0xb91c1c), 0);
    }
}

static void help_event(lv_event_t *event)
{
  lv_event_code_t code = lv_event_get_code(event);

  if (g_ui == NULL)
    {
      return;
    }

  if (code == LV_EVENT_LONG_PRESSED && g_ui->help_timer == NULL)
    {
      g_ui->help_countdown = 5;
      g_ui->ignore_release_click = true;
      lv_label_set_text(g_ui->help_btn_label, "取消求助 5");
      lv_label_set_text(g_ui->help_notice,
                        "正在准备求助，再点一次可取消");
      lv_obj_set_style_text_color(g_ui->help_notice,
                                  lv_color_hex(0xc2410c), 0);
      lv_obj_set_style_bg_color(g_ui->help_button,
                                lv_color_hex(0xea580c), 0);
      g_ui->help_timer = lv_timer_create(help_timer_event, 1000, g_ui);
    }
  else if (code == LV_EVENT_CLICKED)
    {
      if (g_ui->ignore_release_click)
        {
          g_ui->ignore_release_click = false;
          return;
        }

      if (g_ui->help_timer != NULL)
        {
          lv_timer_delete(g_ui->help_timer);
          g_ui->help_timer = NULL;
          help_reset_button();
          lv_label_set_text(g_ui->help_notice, "求助已取消");
          lv_obj_set_style_text_color(g_ui->help_notice,
                                      lv_color_hex(0x15803d), 0);
        }
      else
        {
          lv_label_set_text(g_ui->help_notice,
                            "请长按按钮，避免误触");
          lv_obj_set_style_text_color(g_ui->help_notice,
                                      lv_color_hex(0x64748b), 0);
        }
    }
}

static void setting_slider_event(lv_event_t *event)
{
  lv_event_code_t code;
  int value;
  lv_obj_t *slider;

  code = lv_event_get_code(event);
  if ((code != LV_EVENT_VALUE_CHANGED && code != LV_EVENT_RELEASED) ||
      g_ui == NULL)
    {
      return;
    }

  slider = lv_event_get_target_obj(event);
  value = lv_slider_get_value(slider);
  if (code == LV_EVENT_VALUE_CHANGED)
    {
      lv_label_set_text_fmt(g_ui->volume_label, "提示音量 %d%%", value);
    }
  else
    {
      int ret = velacare_buzzer_set_volume(value);

      if (ret == 0)
        {
          ret = velacare_settings_set_volume(value);
        }
      lv_label_set_text(g_ui->setting_notice,
                        ret == 0 ? "已保存，重启后有效" :
                                   "应用失败，请重试");
      lv_obj_set_style_text_color(g_ui->setting_notice,
                                  lv_color_hex(ret == 0 ? 0x15803d :
                                                           0xb91c1c), 0);
    }
}

