    syslog(LOG_INFO, VELACARE_TAG " TTS 启用: picoTTS (本地)\n");
#else
    syslog(LOG_INFO, VELACARE_TAG " TTS 关闭\n");
#endif
    return 0;
}

/* URL encode 简单实现 (ASCII 即可) */
static void url_encode(const char *src, char *dst, size_t dst_size)
{
    size_t i = 0;
    for (const char *p = src; *p && i + 4 < dst_size; p++)
    {
        unsigned char c = (unsigned char)*p;
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
            (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~')
        {
            dst[i++] = c;
        }
        else if (c == ' ')
        {
            dst[i++] = '+';
        }
        else
        {
            i += snprintf(dst + i, dst_size - i, "%%%02X", c);
        }
    }
    dst[i] = '\0';
}

int velacare_tts_play(const char *text)
{
    if (!text) return -1;

#if CONFIG_VELACARE_TTS_PROVIDER == VELACARE_TTS_BAIDU
    char encoded[512];
    url_encode(text, encoded, sizeof(encoded));

    char url[768];
    snprintf(url, sizeof(url),
             "https://tts.baidu.com/text2audio?tex=%s&spd=4&cuid=velacare&ctp=1", encoded);

    syslog(LOG_INFO, VELACARE_TAG " TTS 播报: %s\n", text);
    /* TODO: 调用 ai_agent 的 music_play 工具 */
    /* 实际通过 nsh: vela> music_play <url> */
    return 0;

#elif CONFIG_VELACARE_TTS_PROVIDER == VELACARE_TTS_LOCAL
    /* picoTTS 离线, 但需要 2MB 字典, D12x 上未实测, 暂不实现 */
    syslog(LOG_WARN, VELACARE_TAG " 本地 TTS 暂未实现\n");
    return -1;

#else
    syslog(LOG_DEBUG, VELACARE_TAG " TTS 关闭, 跳过播报\n");
    return 0;
#endif
}

void velacare_tts_vibrate(int ms)
{
    /* D12x 无振动器, 用屏闪代替 */
    int fd = open("/sys/class/leds/lcd_backlight/brightness", O_WRONLY);
    if (fd < 0) return;

    int orig = 255;
    int n = write(fd, "255", 3);
    (void)n;

    int half = ms / 2;
    for (int i = 0; i < 3; i++)
    {
        write(fd, "0",   1);  usleep(half * 1000);
        write(fd, "255", 3);  usleep(half * 1000);
    }
    (void)orig;
    close(fd);
}
# Voice Alert
语音告警兜底，在 WARNING/EMERGENCY 时自动播报，不需用户主动触发。

## When to use
- 由 home-safety-guard 或 elder-care-reminder 内部调用
- 状态机 level 提升到 WARNING 或 EMERGENCY 时自动激活
- 用户问 "刚才那个报警是什么"、"再说一遍"

## How to use
1. read_file /data/velacare/state.json 拿当前 level
2. 根据 level 拼播报文本:
   - WARNING: "检测到 X 异常，请确认 Y 是否安全"
   - EMERGENCY: "紧急情况！X 持续 N 分钟，已通知家属"
3. 构造 TTS URL: https://tts.baidu.com/text2audio?tex=...&spd=4
4. music_play 播放 MP3
5. WARNING: vibrate 1 秒; EMERGENCY: vibrate 循环直到 level 降级

## TTS 模板
- WARNING 短句: "厨房烟感报警，请检查"
- EMERGENCY 长句: "紧急！厨房烟感持续 5 分钟，已通知你的儿子张三"

## Output format
播报后用文字回报:
- "已播报 WARNING: 厨房烟感报警"
- "已循环播报 EMERGENCY，请立即处理"

## Example
[内部触发] state.level=WARNING
→ TTS URL = "https://tts.baidu.com/text2audio?tex=厨房烟感报警，请检查&spd=4"
→ music_play TTS URL
→ vibrate 1000ms
→ state.json last_voice_alert=now
→ "已播报 WARNING"

## 兜底
- TTS 失败: 退回 vibrate + 屏闪
- vibrate 失败: 屏闪 + 串口持续输出
- 板载无扬声器: 仅 vibrate

