int velacare_tts_init(void)
{
#if CONFIG_VELACARE_TTS_PROVIDER == VELACARE_TTS_BAIDU
    syslog(LOG_INFO, VELACARE_TAG " TTS 启用: 百度 (在线)\n");
#elif CONFIG_VELACARE_TTS_PROVIDER == VELACARE_TTS_LOCAL
    syslog(LOG_INFO, VELACARE_TAG " TTS 启用: picoTTS (本地)\n");
#else
    syslog(LOG_INFO, VELACARE_TAG " TTS 关闭\n");
#endif
    return 0;
}

/* URL encode 简单实现 (ASCII 即可) */
static void url_encode(const char *src, char *dst, size_t dst_size)
{
    size_t i = 0;
    for (const char *p = src; *p && i + 4 < dst_size; p++)
    {
        unsigned char c = (unsigned char)*p;
        if ((c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z') ||
            (c >= '0' && c <= '9') || c == '-' || c == '_' || c == '.' || c == '~')
        {
            dst[i++] = c;
        }
        else if (c == ' ')
        {
            dst[i++] = '+';
        }
        else
        {
            i += snprintf(dst + i, dst_size - i, "%%%02X", c);
        }
    }
    dst[i] = '\0';
}

int velacare_tts_play(const char *text)
{
    if (!text) return -1;

#if CONFIG_VELACARE_TTS_PROVIDER == VELACARE_TTS_BAIDU
    char encoded[512];
    url_encode(text, encoded, sizeof(encoded));

    char url[768];
    snprintf(url, sizeof(url),
             "https://tts.baidu.com/text2audio?tex=%s&spd=4&cuid=velacare&ctp=1", encoded);

    syslog(LOG_INFO, VELACARE_TAG " TTS 播报: %s\n", text);
    /* TODO: 调用 ai_agent 的 music_play 工具 */
    /* 实际通过 nsh: vela> music_play <url> */
    return 0;

#elif CONFIG_VELACARE_TTS_PROVIDER == VELACARE_TTS_LOCAL
    /* picoTTS 离线, 但需要 2MB 字典, D12x 上未实测, 暂不实现 */
    syslog(LOG_WARN, VELACARE_TAG " 本地 TTS 暂未实现\n");
    return -1;

#else
    syslog(LOG_DEBUG, VELACARE_TAG " TTS 关闭, 跳过播报\n");
    return 0;
#endif
}

void velacare_tts_vibrate(int ms)
{
    /* D12x 无振动器, 用屏闪代替 */
    int fd = open("/sys/class/leds/lcd_backlight/brightness", O_WRONLY);
    if (fd < 0) return;

    int orig = 255;
    int n = write(fd, "255", 3);
    (void)n;

    int half = ms / 2;
    for (int i = 0; i < 3; i++)
    {
        write(fd, "0",   1);  usleep(half * 1000);
        write(fd, "255", 3);  usleep(half * 1000);
    }
    (void)orig;
    close(fd);
}
